<!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Đặt lịch | NALI</title><link rel="stylesheet" href="common.css">
    <link rel="stylesheet" href="dental-theme.css"><link rel="stylesheet" href="content-pages.css"><style>.bw{max-width:800px;margin:38px auto 70px;padding:0 18px}.p{display:flex;gap:8px}.p span{flex:1;padding:10px;text-align:center;background:#e5eef2;border-radius:8px}.p .on{background:#147db0;color:#fff}.s{display:none}.s.on{display:block}.choices,.slots{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.choices label,.slots button{border:1px solid #b8d1dd;padding:12px;border-radius:10px;background:#fff}.slots button:disabled{opacity:.4}.nav{display:flex;justify-content:space-between;margin-top:22px}.nav button{padding:12px 18px;border:0;border-radius:9px;background:#147db0;color:white;font-weight:bold}@media(max-width:600px){.choices,.slots{grid-template-columns:repeat(2,1fr)}}</style></head><body>
