<form id="booking-form"><section class="s on"><div class="choices"><?php foreach($products as $x): ?><label><input type="radio" name="service" value="<?=htmlspecialchars($x['name'],ENT_QUOTES)?>" data-group="<?=htmlspecialchars($x['target_group'],ENT_QUOTES)?>"><b><?=htmlspecialchars($x['name'])?></b><br><small><?=number_format((float)$x['price'],0,',','.')?>đ</small></label><?php endforeach; ?></div><label>Mã ưu đãi <input id="booking-code" maxlength="40"></label><div class="nav"><i></i><button type="button" data-next>Tiếp</button></div></section>
<section class="s"><label>Ngày hẹn <input id="booking-date" type="date" min="<?=date('Y-m-d')?>"></label><p id="slot-info">Chọn ngày để xem giờ còn trống.</p><div class="slots" id="slot-grid"></div><input id="booking-time" type="hidden"><div class="nav"><button type="button" data-back>Quay lại</button><button type="button" data-next>Tiếp</button></div></section>
