<?php renderFooter(); ?>
<script>
const wizard=document.getElementById('booking-form'), steps=[...document.querySelectorAll('.s')], bars=[...document.querySelectorAll('.p span')], dateInput=document.getElementById('booking-date'), timeInput=document.getElementById('booking-time'), slotGrid=document.getElementById('slot-grid'), info=document.getElementById('slot-info'); let current=0;
function showStep(n){current=n;steps.forEach((x,i)=>x.classList.toggle('on',i===n));bars.forEach((x,i)=>x.classList.toggle('on',i===n));}
function stepValid(){if(current===0)return !!document.querySelector('[name=service]:checked');if(current===1)return !!dateInput.value&&!!timeInput.value;return true;}
document.querySelectorAll('[data-next]').forEach(x=>x.onclick=()=>stepValid()?showStep(current+1):alert('Vui lòng hoàn thành bước này.'));
document.querySelectorAll('[data-back]').forEach(x=>x.onclick=()=>showStep(current-1));
dateInput.onchange=async()=>{timeInput.value='';slotGrid.innerHTML='';info.textContent='Đang tải khung giờ…';try{const response=await fetch('booking_slots.php?date='+encodeURIComponent(dateInput.value));const data=await response.json();(data.slots||[]).forEach(slot=>{const button=document.createElement('button');button.type='button';button.textContent=slot.time;button.disabled=!slot.available;button.onclick=()=>{[...slotGrid.children].forEach(x=>x.style.background='');button.style.background='#dff4fb';timeInput.value=slot.time};slotGrid.append(button)});info.textContent='Giờ mờ đã kín.'}catch(e){info.textContent='Không tải được khung giờ. Vui lòng thử lại.'}};
wizard.onsubmit=async event=>{event.preventDefault();const selected=document.querySelector('[name=service]:checked'), phone=document.getElementById('booking-phone'), submit=document.getElementById('booking-go');if(!selected||!/^0\d{9}$/.test(phone.value)){alert('Kiểm tra dịch vụ và số điện thoại.');return;}submit.disabled=true;const payload={service:selected.value,category:selected.dataset.group,date:dateInput.value,time:timeInput.value,name:document.getElementById('booking-name').value.trim(),phone:phone.value,email:document.getElementById('booking-email').value.trim(),notes:document.getElementById('booking-notes').value.trim(),discount_code:document.getElementById('booking-code').value.trim()};try{const response=await fetch('book_appointment.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const data=await response.json();document.getElementById('booking-message').textContent=data.success?'Đã giữ lịch #'+data.appointment_id+'. Phòng khám sẽ xác nhận lại.':data.message;if(data.success){wizard.reset();showStep(0)}}catch(e){document.getElementById('booking-message').textContent='Không kết nối được máy chủ.'}finally{submit.disabled=false}};
</script></body></html>
